#include "custom_mail_catalog.hpp"
#include "embedded_assets.hpp"
#include "json.hpp"
#include <mutex>
#include <set>
#include <unordered_map>
namespace astrae::lobby {
namespace {
struct Catalog { bool loaded=false;std::string error;uint64_t base_id=0;size_t range=0;std::vector<CustomMailItem> items;std::vector<std::vector<CustomMailChoice>> choices;std::vector<int32_t> resolver; };
Catalog &catalog(){static Catalog value;return value;}
std::once_flag &catalog_once(){static std::once_flag value;return value;}
void load_catalog(){auto &out=catalog();try{std::string raw;if(!assets::read_embedded_asset("assets/tables/embedded_11_custom_mail.json",raw)){out.error="embedded Custom Mail asset is unavailable";return;}const auto root=json::parse(raw);if(!root.is_object()||root["formatVersion"].as_u64()!=1){out.error="unsupported Custom Mail asset format";return;}const auto &item_rows=root["items"].as_array(),&choice_rows=root["choices"].as_array(),&resolver_rows=root["resolver"]["indexByOffset"].as_array();out.base_id=root["resolver"]["baseParcelId"].as_u64();out.range=static_cast<size_t>(root["resolver"]["range"].as_u64());if(!out.base_id||!out.range||resolver_rows.size()!=out.range||item_rows.size()!=22||choice_rows.size()!=715){out.error="Custom Mail asset count or resolver bounds mismatch";return;}std::unordered_map<uint64_t,size_t> index_by_id;std::set<std::pair<uint64_t,uint64_t>> unique_choices;out.items.reserve(item_rows.size());out.choices.resize(item_rows.size());for(const auto &row:item_rows){CustomMailItem item;item.parcel_id=row["parcelId"].as_u64();item.type=static_cast<uint32_t>(row["type"].as_u64());item.name=row["name"].as_string();item.description=row["description"].as_string();if(!item.parcel_id||item.name.empty()||item.description.empty()||index_by_id.count(item.parcel_id)){out.error="Custom Mail descriptor contains an invalid or duplicate item";return;}index_by_id.emplace(item.parcel_id,out.items.size());out.items.push_back(std::move(item));}for(const auto &row:choice_rows){CustomMailChoice choice;choice.item=row["item"].as_u64();choice.id=row["id"].as_u64();choice.type=static_cast<uint32_t>(row["type"].as_u64());auto it=index_by_id.find(choice.item);if(it==index_by_id.end()||choice.type!=out.items[it->second].type||!unique_choices.insert({choice.item,choice.id}).second){out.error="Custom Mail choice references an unknown item, mismatched type or duplicate item/id pair";return;}out.choices[it->second].push_back(choice);}out.resolver.reserve(resolver_rows.size());size_t mapped=0;for(size_t offset=0;offset<resolver_rows.size();++offset){const auto &entry=resolver_rows[offset];if(entry.is_null()){out.resolver.push_back(-1);continue;}const uint64_t index=entry.as_u64();if(index>=out.items.size()||out.items[static_cast<size_t>(index)].parcel_id!=out.base_id+offset){out.error="Custom Mail resolver index does not match descriptor parcel ID";return;}out.resolver.push_back(static_cast<int32_t>(index));++mapped;}if(mapped!=out.items.size()){out.error="Custom Mail resolver does not cover every descriptor exactly once";return;}for(size_t i=0;i<out.items.size();++i)if(out.choices[i].empty()){out.error="Custom Mail descriptor has no choice rows: "+std::to_string(out.items[i].parcel_id);return;}out.loaded=true;}catch(const std::exception &e){out.error=std::string("Custom Mail asset parse/validation failed: ")+e.what();}}
}
bool ensure_custom_mail_catalog(std::string *error){std::call_once(catalog_once(),load_catalog);const auto &value=catalog();if(error)*error=value.error;return value.loaded;}
const CustomMailItem *resolve_custom_mail_item(uint64_t parcel_id){if(!ensure_custom_mail_catalog())return nullptr;const auto &value=catalog();if(parcel_id<value.base_id||parcel_id-value.base_id>=value.range)return nullptr;const int32_t index=value.resolver[static_cast<size_t>(parcel_id-value.base_id)];return index<0?nullptr:&value.items[static_cast<size_t>(index)];}
const CustomMailItem *custom_mail_item_at(size_t index){if(!ensure_custom_mail_catalog())return nullptr;const auto &value=catalog();return index<value.items.size()?&value.items[index]:nullptr;}
const std::vector<CustomMailChoice> *custom_mail_choices(uint64_t parcel_id){const auto *item=resolve_custom_mail_item(parcel_id);if(!item)return nullptr;const auto &value=catalog();const size_t index=static_cast<size_t>(item-value.items.data());return &value.choices[index];}
size_t custom_mail_item_count(){return ensure_custom_mail_catalog()?catalog().items.size():0;}
size_t custom_mail_choice_count(){if(!ensure_custom_mail_catalog())return 0;size_t total=0;for(const auto &items:catalog().choices)total+=items.size();return total;}
}
